CREATE OR REPLACE FUNCTION ojjuda_note_internal.enforce_note_blocked_words()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  IF auth.uid() IS NULL AND (TG_OP <> 'INSERT' OR NEW.author_id IS NOT NULL) THEN
    RAISE EXCEPTION 'Sign in required' USING ERRCODE = '42501';
  END IF;
  IF public.has_banned(coalesce(NEW.body, '')) OR EXISTS (
    SELECT 1 FROM unnest(coalesce(NEW.tags, ARRAY[]::text[])) AS tag(value)
    WHERE public.has_banned(tag.value)
  ) THEN
    RAISE EXCEPTION '노트 운영 기준에 맞지 않는 표현이 포함되어 있어요.' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.check_banned_cols()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
declare col text; v text; changed boolean;
begin
  foreach col in array TG_ARGV loop
    if TG_OP = 'UPDATE' then
      execute format('select ($1).%I::text is distinct from ($2).%I::text', col, col) into changed using new, old;
      if not changed then continue; end if;
    end if;
    execute format('select ($1).%I::text', col) into v using new;
    if v is not null and public.has_banned(v) then
      raise exception 'banned_word' using errcode = 'P0001', hint = '욕설, 음란, 마약 관련 표현은 쓸 수 없어요';
    end if;
  end loop;
  return new;
end $function$

CREATE OR REPLACE FUNCTION ojjuda_note_internal.admin_reply_inquiry(p_id uuid, p_reply text, p_expected_updated_at timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF NOT ojjuda_note_internal.is_note_moderator() THEN RAISE EXCEPTION 'Note moderator required' USING ERRCODE='42501'; END IF;
 IF p_reply IS NULL OR char_length(btrim(p_reply)) NOT BETWEEN 1 AND 2000 OR p_expected_updated_at IS NULL THEN RAISE EXCEPTION 'Invalid reply' USING ERRCODE='22023'; END IF;
 UPDATE ojjuda_note_internal.inquiries SET reply=btrim(p_reply),status='resolved',replied_by=auth.uid(),updated_at=clock_timestamp() WHERE id=p_id AND updated_at=p_expected_updated_at;
 IF NOT FOUND THEN RAISE EXCEPTION '문의가 변경됐어요. 새로 불러온 뒤 답변해 주세요.' USING ERRCODE='40001'; END IF;
 -- Record the action without copying private inquiry content to the audit feed.
 INSERT INTO ojjuda_note_internal.moderation_actions(moderator_id,subject_user_id,action,reason,detail) SELECT auth.uid(),i.user_id,'reply_inquiry','노트 문의 답변',jsonb_build_object('inquiry_id',p_id) FROM ojjuda_note_internal.inquiries i WHERE i.id=p_id;
END $function$

CREATE OR REPLACE FUNCTION ojjuda_note_internal.send_friend_message(p_recipient uuid, p_body text, p_request uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE viewer uuid:=auth.uid(); clean text:=regexp_replace(p_body,'^\s+|\s+$','','g'); item ojjuda_note_internal.friend_messages;
BEGIN
 IF viewer IS NULL OR NOT EXISTS(SELECT 1 FROM auth.users WHERE id=viewer) THEN RAISE EXCEPTION 'sign_in_required' USING ERRCODE='42501'; END IF;
 IF p_recipient IS NULL OR viewer=p_recipient OR p_request IS NULL OR clean IS NULL OR length(clean) NOT BETWEEN 1 AND 1000 OR octet_length(clean)>4000 THEN RAISE EXCEPTION 'invalid_message' USING ERRCODE='22023'; END IF;
 -- Serialize this sender's retries/rate checks without locking any other account.
 PERFORM pg_advisory_xact_lock(hashtextextended('friend_message:'||viewer::text,0));
 IF public.is_banned(viewer) OR ojjuda_note_internal.friend_message_blocked(p_recipient)
 OR NOT EXISTS(SELECT 1 FROM public.friendships f WHERE f.status='accepted' AND ((f.requester=viewer AND f.addressee=p_recipient) OR (f.requester=p_recipient AND f.addressee=viewer)))
 OR NOT EXISTS(SELECT 1 FROM auth.users WHERE id=p_recipient) THEN RAISE EXCEPTION 'friend_message_unavailable' USING ERRCODE='42501'; END IF;
 SELECT * INTO item FROM ojjuda_note_internal.friend_messages WHERE sender_id=viewer AND request_id=p_request;
 IF FOUND THEN
  IF item.recipient_id<>p_recipient OR item.body<>clean THEN RAISE EXCEPTION 'request_conflict' USING ERRCODE='22023'; END IF;
  RETURN jsonb_build_object('ok',true,'id',item.id,'replayed',true);
 END IF;
 IF (SELECT count(*) FROM ojjuda_note_internal.friend_messages WHERE sender_id=viewer AND created_at>clock_timestamp()-interval '1 minute')>=20 THEN RAISE EXCEPTION 'message_rate_limit' USING ERRCODE='P0001'; END IF;
 INSERT INTO ojjuda_note_internal.friend_messages(sender_id,recipient_id,body,request_id) VALUES(viewer,p_recipient,clean,p_request) RETURNING * INTO item;
 RETURN jsonb_build_object('ok',true,'id',item.id,'replayed',false);
END $function$

CREATE OR REPLACE FUNCTION ojjuda_note_internal.submit_inquiry(p_request_id uuid, p_body text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE result_id uuid;
BEGIN
 IF NOT ojjuda_note_internal.is_world_member() THEN RAISE EXCEPTION 'World membership required' USING ERRCODE='42501'; END IF;
 IF p_request_id IS NULL OR p_body IS NULL OR char_length(btrim(p_body)) NOT BETWEEN 1 AND 2000 THEN RAISE EXCEPTION 'Invalid inquiry' USING ERRCODE='22023'; END IF;
 -- Serialize each author's submissions, including concurrent retries and quota checks.
 PERFORM pg_advisory_xact_lock(hashtextextended('note-inquiry:'||auth.uid()::text,0));
 SELECT i.id INTO result_id FROM ojjuda_note_internal.inquiries i WHERE i.user_id=auth.uid() AND i.request_id=p_request_id;
 IF result_id IS NOT NULL THEN RETURN result_id; END IF;
 IF (SELECT count(*) FROM ojjuda_note_internal.inquiries i WHERE i.user_id=auth.uid() AND i.created_at>now()-interval '24 hours')>=3 THEN
  RAISE EXCEPTION '하루에 문의를 3개까지 보낼 수 있어요.' USING ERRCODE='22023';
 END IF;
 INSERT INTO ojjuda_note_internal.inquiries(user_id,request_id,body) VALUES(auth.uid(),p_request_id,btrim(p_body)) RETURNING id INTO result_id;
 RETURN result_id;
END $function$

CREATE OR REPLACE FUNCTION public.has_banned(t text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n text; a record;
begin
  n := norm_text(t);
  if n = '' then return false; end if;
  for a in select phrase from banned_allow loop n := replace(n, norm_text(a.phrase), ''); end loop;
  return exists (select 1 from banned_base b where b.active and norm_text(b.word) <> '' and position(norm_text(b.word) in n) > 0)
      or exists (select 1 from banned_words w where norm_text(w.word) <> '' and position(norm_text(w.word) in n) > 0);
end $function$

CREATE OR REPLACE FUNCTION ojjuda_groups_internal.activity_labels(items jsonb, require_unique boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare item jsonb; label text; labels jsonb:='[]';
begin
  if jsonb_typeof(items) is distinct from 'array' then raise exception '항목을 입력해 주세요.'; end if;
  if jsonb_array_length(items) not between 2 and 10 then raise exception '항목은 2~10개 입력해 주세요.'; end if;
  for item in select value from jsonb_array_elements(items) loop
    label:=btrim(item #>> '{}');
    if jsonb_typeof(item)<>'string' or length(label) not between 1 and 40 or label ~ '[[:cntrl:]]' then
      raise exception '각 항목은 한 줄에 1~40자로 입력해 주세요.';
    end if;
    if require_unique and labels ? label then raise exception '같은 이름의 항목을 구분해 주세요.'; end if;
    if public.has_banned(label) then raise exception 'banned_word'; end if;
    labels:=labels || jsonb_build_array(label);
  end loop;
  return labels;
end $function$

CREATE OR REPLACE FUNCTION public.admin_rename_user(p_user uuid, p_nick text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_nick text := btrim(coalesce(p_nick, '')); v_old text;
begin
  if not public.is_admin() then raise exception 'not_admin'; end if;
  if char_length(v_nick) < 1 or char_length(v_nick) > 12 then raise exception 'bad_nick'; end if;
  if exists (select 1 from public.profiles p where p.nickname = v_nick and p.id <> p_user) then raise exception 'nick_taken'; end if;
  select p.nickname into v_old from public.profiles p where p.id = p_user;
  if not found then raise exception 'not_found'; end if;
  update public.profiles p set nickname = v_nick where p.id = p_user;
  perform public.admin_note('rename', p_user, v_nick, jsonb_build_object('old', v_old));
end $function$

CREATE OR REPLACE FUNCTION public.ensure_member_for_note(p_nickname text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := (select auth.uid());
  v_name text;
begin
  if v_uid is null then
    raise exception 'sign_in_required' using errcode = '42501';
  end if;

  if not exists (select 1 from public.profiles where id = v_uid) then
    v_name := pg_catalog.btrim(p_nickname);
    if v_name is null or pg_catalog.char_length(v_name) not between 1 and 12 then
      raise exception 'nickname_required' using errcode = '22023';
    end if;
    insert into public.profiles (id, nickname)
    values (v_uid, v_name)
    on conflict (id) do nothing;
  end if;

  insert into public.user_private (user_id)
  values (v_uid)
  on conflict (user_id) do nothing;
  return true;
end;
$function$
